import{_ as t,o as e,c as d,a3 as a}from"./chunks/framework.CVt6dz2a.js";const r="/threejs-tutorial-site/assets/EP.35-undo-stack.CB4Xe-Df.svg",m=JSON.parse('{"title":"EP.35 按错一次，悔十次","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.35-undo-stack.md","filePath":"comics/EP.35-undo-stack.md","lastUpdated":1793881879000}'),u={name:"comics/EP.35-undo-stack.md"};function i(c,o,s,n,l,q){return e(),d("div",null,[...o[0]||(o[0]=[a('<h1 id="ep-35-按错一次-悔十次" tabindex="-1">EP.35 按错一次，悔十次 <a class="header-anchor" href="#ep-35-按错一次-悔十次" aria-label="Permalink to &quot;EP.35 按错一次，悔十次&quot;">​</a></h1><p><img src="'+r+'" alt="EP.35 撤销栈与序列化：像素酱拖歪了物体，码叔与标签君搬出命令模式、双栈与最小 JSON"></p><blockquote><p><strong>对应正文</strong>：<a href="./../guide/35-scene-editor/basics">35.1 基础入门：选择、变换操控与 gizmo</a><strong>延伸阅读</strong>：<a href="./../guide/35-scene-editor/advanced">35.2 进阶应用：场景图、撤销重做与序列化</a> · <a href="./../guide/35-scene-editor/practice">35.3 实战案例：可保存的迷你场景编辑器</a><strong>动手演示</strong>：<a href="./../public/demos/scene-editor/gizmo-lab.html">gizmo-lab 选择与操控台</a> · <a href="./../public/demos/scene-editor/undo-serialization-lab.html">undo-serialization-lab 撤销与序列化实验室</a> · <a href="./../public/demos/scene-editor/mini-editor.html">mini-editor 迷你编辑器</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>画面</th><th>关键对白</th><th>梗 / 记忆点</th></tr></thead><tbody><tr><td>1</td><td>像素酱把方块拖歪，原来的位置只剩虚线；代码写着 <code>position.x += 2</code></td><td>&quot;拖歪了……刚才的位置还能回去吗？&quot;</td><td>直接改对象，旧值没有留底，撤销无从谈起</td></tr><tr><td>2</td><td>码叔画出命令卡片：<code>do()</code> 做事，<code>undo()</code> 还原</td><td>&quot;每次修改都包成命令：do 做事，undo 还原。&quot;</td><td>命令要同时知道&quot;怎么做&quot;和&quot;怎么撤&quot;</td></tr><tr><td>3</td><td>标签君搬出撤销栈、重做栈与一条 JSON</td><td>&quot;连续拖拽合并成一条，场景只存最小信息。&quot;</td><td>合并靠同对象 + 时间窗，新操作清空重做栈</td></tr><tr><td>4</td><td>码叔总结三条纪律，标签君把坑点贴上墙</td><td>&quot;所有修改走命令，场景存成最小 JSON。&quot;</td><td>能撤销，才敢真用；坏 JSON 不能崩</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-编辑器不能只-改-还要-记得" tabindex="-1">1. 编辑器不能只&quot;改&quot;，还要&quot;记得&quot; <a class="header-anchor" href="#_1-编辑器不能只-改-还要-记得" aria-label="Permalink to &quot;1. 编辑器不能只&quot;改&quot;，还要&quot;记得&quot;&quot;">​</a></h3><p>直接 <code>scene.add()</code>、直接改 <code>position</code>、直接 <code>remove()</code> 是 Three.js 的日常写法，但它们都有一个共同点：<strong>旧状态当场消失</strong>。渲染不在乎，编辑器却很在乎。撤销的本质不是&quot;时光倒流&quot;，而是&quot;保留足够的信息，把改动反向执行一遍&quot;。</p><p>所以在编辑器里，&quot;改&quot;这个动作要升级成&quot;提交一条可逆的命令&quot;。这条命令至少要携带：操作对象是谁、改之前是什么、改之后是什么。没有这三样，撤销就是空谈。</p><h3 id="_2-命令模式-do-与-undo-是一对逆运算" tabindex="-1">2. 命令模式：<code>do()</code> 与 <code>undo()</code> 是一对逆运算 <a class="header-anchor" href="#_2-命令模式-do-与-undo-是一对逆运算" aria-label="Permalink to &quot;2. 命令模式：`do()` 与 `undo()` 是一对逆运算&quot;">​</a></h3><p>命令模式把&quot;修改&quot;封装成对象，对外只暴露两个方法：</p><ul><li><code>do()</code>：执行修改，或重做时再次执行；</li><li><code>undo()</code>：把修改精确地反向执行。</li></ul><p>现实里的命令不止变换一种。添加物体的 <code>AddCommand</code>，撤销是&quot;移除&quot;；删除物体的 <code>DeleteCommand</code>，撤销是&quot;按原索引插回&quot;；改颜色的 <code>MaterialCommand</code>，撤销是&quot;恢复旧颜色&quot;。每种命令都要单独保证自己的逆运算正确，这是命令式撤销最大的成本，也是它最大的价值。</p><h3 id="_3-合并与两个栈-历史要-少而准" tabindex="-1">3. 合并与两个栈：历史要&quot;少而准&quot; <a class="header-anchor" href="#_3-合并与两个栈-历史要-少而准" aria-label="Permalink to &quot;3. 合并与两个栈：历史要&quot;少而准&quot;&quot;">​</a></h3><p>一次拖拽会产生上百个 <code>objectChange</code>，如果每次都入栈，撤销一次只退一帧。正确做法是按<strong>拖拽生命周期</strong>提交：按下拍&quot;前&quot;快照，松开拍&quot;后&quot;快照，中间的变化只用来实时预览。再叠一层&quot;同对象 + 700ms 时间窗&quot;的合并，连续拖几次也只留一条。</p><p>历史由两个数组组成：撤销栈存&quot;已经发生&quot;的命令，重做栈存&quot;被撤销、还能再来一次&quot;的命令。规则只有一条——<strong>任何新操作都要清空重做栈</strong>，否则用户会在&quot;未来&quot;里重放一条不该存在的命令。</p><h3 id="_4-序列化-只存-可重建的最小信息" tabindex="-1">4. 序列化：只存&quot;可重建的最小信息&quot; <a class="header-anchor" href="#_4-序列化-只存-可重建的最小信息" aria-label="Permalink to &quot;4. 序列化：只存&quot;可重建的最小信息&quot;&quot;">​</a></h3><p>场景 JSON 不是 Three.js 对象的转储。几何的顶点数组、贴图的像素、GPU 的 program，全都不该进 JSON。真正需要保存的只有：id、类型、变换（位置 + 四元数 + 缩放）、材质引用、父子关系，以及少量业务字段。</p><p>反序列化时先校验、后清场、再重建：版本号不能高于当前支持、节点数量有上限、未知类型跳过、id 冲突要重映射。坏文件最多导入失败，绝不能让当前场景一起消失。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>误区一：把对象引用直接 <code>JSON.stringify</code>。</strong> Three.js 对象里有大量循环引用和运行时资源，序列化函数必须显式挑选字段，不能图省事。</li><li><strong>误区二：命令里的 <code>before</code> 存的是可变引用。</strong> <code>before = obj.position</code> 会跟着拖拽一起变，撤销时等于&quot;撤销到当前位置&quot;，看起来像没生效。必须克隆。</li><li><strong>误区三：在 <code>input</code> 事件里提交命令。</strong> 颜色选择器拖一下、数字框敲一个字都会产生几十条历史。正确节奏是 <code>input</code> 预览、<code>change</code> 提交。</li><li><strong>误区四：新操作忘了清空重做栈。</strong> 表现为撤销两步、新加一个物体，再按重做时场景里冒出旧物体。所有写历史的入口都要清空 <code>redoStack</code>。</li></ul><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>Q1：一条合格的 `TransformCommand` 至少需要哪三样信息？</b></summary><p>操作对象、改之前的 TRS 快照、改之后的 TRS 快照。<code>do()</code> 应用 after，<code>undo()</code> 应用 before。快照必须是克隆出来的副本，不能引用对象当前的可变属性。</p></details><details><summary><b>Q2：连续拖拽合并成一条，边界条件有哪些？</b></summary><p>至少四条：同一对象、同一类命令、在时间窗口内（通常 700ms 左右）、期间没有切换选中或撤销重做。更严谨的做法是给每次操作一个 <code>mergeKey</code>，只有 key 相同才合并。</p></details><details><summary><b>Q3：为什么场景 JSON 里不存几何顶点和贴图？</b></summary><p>因为它们可以由&quot;类型 + 参数&quot;重建，或者由资源 URL 在运行时加载。把它们写进 JSON 会让体积爆炸、跨端难以复用，而且 GPU 资源本来就无法序列化。JSON 只负责描述&quot;场景里有什么、在哪里、长什么样&quot;。</p></details><hr><blockquote><p>下一篇正文见 <a href="./../guide/35-scene-editor/basics">35.1 基础入门：选择、变换操控与 gizmo</a>。漫画仅作概念预热，代码与验收细节以正文为准。</p></blockquote>',27)])])}const p=t(u,[["render",i]]);export{m as __pageData,p as default};
